package com.sacco.mvp.config;

import com.sacco.mvp.domain.*;
import com.sacco.mvp.grouplending.controller.GroupCoverageController;
import com.sacco.mvp.grouplending.controller.GroupCoverageDocumentController;
import com.sacco.mvp.grouplending.dto.GroupCoverageDtos.*;
import com.sacco.mvp.grouplending.dto.GroupCoverageDtos.Case;
import com.sacco.mvp.grouplending.dto.GroupLendingDtos.Page;
import com.sacco.mvp.grouplending.service.GroupCoverageService;
import com.sacco.mvp.grouplending.service.GroupCoveragePdf;
import com.sacco.mvp.security.AppUserPrincipal;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.*;
import org.springframework.test.context.junit.jupiter.web.SpringJUnitWebConfig;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.web.servlet.config.annotation.EnableWebMvc;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringJUnitWebConfig({MvcSecurityTestConfiguration.class,GroupCoverageWorkspaceMvcTest.Config.class})
class GroupCoverageWorkspaceMvcTest {
    @Autowired WebApplicationContext context;@Autowired GroupCoverageService service;@Autowired GroupCoveragePdf pdf;MockMvc mvc;AppUserPrincipal staff,client;UUID cycle=UUID.randomUUID(),id=UUID.randomUUID(),source=UUID.randomUUID(),posting=UUID.randomUUID(),link=UUID.randomUUID();Case header;Policy policy;CaseContext data;LocalDate day=LocalDate.of(2026,10,25);
    String staffPath(){return "/finance/groups/cycles/"+cycle+"/coverage";}String ownPath(){return "/app/group-coverage/"+id;}
    @BeforeEach void setup(){reset(service);mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();staff=new AppUserPrincipal(Member.builder().id(UUID.randomUUID()).saccoId("I1").stationId("B1").position(Position.ACCOUNTANT).staffAccessStatus(StaffAccessStatus.ACTIVE).status(MemberStatus.ACTIVE).build(),EnumSet.allOf(UserClaim.class),true);client=new AppUserPrincipal(Member.builder().id(UUID.randomUUID()).saccoId("I1").stationId("B1").position(Position.MEMBER).memberAccount(true).status(MemberStatus.ACTIVE).build(),EnumSet.allOf(UserClaim.class),false);header=mock(Case.class);when(header.id()).thenReturn(id);when(header.cycle()).thenReturn(cycle);when(header.expiresOn()).thenReturn(day.plusDays(30));when(header.state()).thenReturn("CALLED");policy=new Policy(UUID.randomUUID(),1,14,30,7,"Synthetic approved policy",true);data=new CaseContext(header,policy,new NoticeFacts(day.minusDays(15),day.minusDays(15),"Private borrower evidence","Private service evidence","notices.pdf"),day);when(service.caseContext(any(),eq(id),anyBoolean(),nullable(String.class))).thenReturn(data);when(service.context(any(),eq(cycle))).thenReturn(new com.sacco.mvp.grouplending.dto.GroupCoverageDtos.Context(cycle,"Synthetic group","Synthetic product"));when(service.policy(any(),eq(cycle))).thenReturn(Optional.of(policy));}
    CallPreparation preparation(){var s=mock(Source.class);when(s.id()).thenReturn(source);when(s.kind()).thenReturn("PERSONAL");return new CallPreparation(new com.sacco.mvp.grouplending.dto.GroupCoverageDtos.Context(cycle,"Synthetic group","Product"),s,policy,new BigDecimal("100.00"));}
    @Test void everyMutationRequiresCsrf()throws Exception{for(var path:List.of(staffPath(),staffPath()+"/policy",staffPath()+"/"+id+"/close",staffPath()+"/"+id+"/link",staffPath()+"/"+id+"/links/"+link+"/correct"))mvc.perform(post(path).with(user(staff))).andExpect(status().isForbidden());mvc.perform(post(ownPath()+"/respond").with(user(client))).andExpect(status().isForbidden());verifyNoInteractions(service);}
    @Test void requestAndPolicyBindingCannotChangeScopeCapsOrHistory()throws Exception{
        when(service.call(eq(staff),eq(cycle),any(),isNull())).thenReturn(id);mvc.perform(post(staffPath()).with(user(staff)).with(csrf()).param("sourceId",source.toString()).param("sourceKind","PERSONAL").param("policyId",policy.id().toString()).param("amount","70.25").param("noticesVerified","true").param("noticeLanguage","BOTH").param("saccoId","FOREIGN").param("sourceCap","1.00").param("received","99999.00").param("state","RECEIVED")).andExpect(redirectedUrl(staffPath()+"/"+id));verify(service).call(eq(staff),eq(cycle),argThat(f->f.getSourceId().equals(source)&&f.getAmount().toPlainString().equals("70.25")&&f.isNoticesVerified()&&f.getNoticeLanguage().equals("BOTH")),isNull());
        mvc.perform(post(staffPath()+"/policy").with(user(staff)).with(csrf()).param("noticeDays","14").param("caseDays","30").param("promiseDays","7").param("reference","Checked policy").param("enabled","true").param("verified","true").param("revision","99").param("saccoId","FOREIGN")).andExpect(redirectedUrl(staffPath()));verify(service).configure(eq(staff),eq(cycle),argThat(f->f.getNoticeDays()==14&&f.isVerified()&&f.getReference().equals("Checked policy")));
    }
    @Test void invalidAmountsRetainEnteredNoticeEvidenceAndShowFieldRecovery()throws Exception{
        when(service.call(eq(staff),eq(cycle),any(),isNull())).thenThrow(new IllegalArgumentException("coverage.error.cap"));var prep=preparation();when(service.prepare(eq(staff),eq(cycle),anyString())).thenReturn(prep);var result=mvc.perform(post(staffPath()).with(user(staff)).with(csrf()).param("sourceId",source.toString()).param("sourceKind","PERSONAL").param("amount","9999.99").param("borrowerNoticeEvidence","Retain borrower proof").param("personNoticeEvidence","Retain named recipient proof").param("noticeLanguage","SW")).andExpect(status().isOk()).andExpect(view().name("groups/coverage-form")).andExpect(model().attributeHasFieldErrors("coverageCallForm","amount")).andReturn();var f=(CallForm)result.getModelAndView().getModel().get("coverageCallForm");assertThat(f.getBorrowerNoticeEvidence()).isEqualTo("Retain borrower proof");assertThat(f.getPersonNoticeEvidence()).isEqualTo("Retain named recipient proof");assertThat(f.getAmount()).isEqualByComparingTo("9999.99");
    }
    @Test void personallyBoundResponsesAndLinksIgnoreImpersonationAndMoneyInputs()throws Exception{
        mvc.perform(post(ownPath()+"/respond").with(user(client)).with(csrf()).param("kind","PROMISED").param("amount","25.00").param("promiseOn","2026-10-30").param("reason","My promise").param("confirmed","true").param("clientId",UUID.randomUUID().toString())).andExpect(redirectedUrl(ownPath()));verify(service).respond(eq(client),eq(id),argThat(f->f.getKind().equals("PROMISED")&&f.getAmount().toPlainString().equals("25.00")&&f.isConfirmed()));
        mvc.perform(post(staffPath()+"/"+id+"/link").with(user(staff)).with(csrf()).param("postingId",posting.toString()).param("payerEvidence","Actual checked payer").param("payerVerified","true").param("amount","999999.99").param("principal","0.01").param("actorId",client.getMemberId().toString())).andExpect(redirectedUrl(staffPath()+"/"+id));verify(service).link(eq(staff),eq(id),argThat(f->f.getPostingId().equals(posting)&&f.isPayerVerified()&&f.getPayerEvidence().equals("Actual checked payer")));
    }
    @Test void wrongCycleAndClientStaffCrossoversCannotReachCommandsOrExports()throws Exception{
        mvc.perform(get(staffPath()).with(user(client))).andExpect(status().isForbidden());when(header.cycle()).thenReturn(UUID.randomUUID());mvc.perform(post(staffPath()+"/"+id+"/close").with(user(staff)).with(csrf()).param("kind","CLOSED").param("reason","Wrong route").param("confirmed","true")).andExpect(status().isForbidden());verify(service,never()).close(any(),any(),any());mvc.perform(get(staffPath()+"/"+id+"/notice/pdf").with(user(staff))).andExpect(status().isForbidden());verify(service,never()).notice(any(),any(),anyBoolean());when(service.caseContext(eq(client),eq(id),eq(true),nullable(String.class))).thenThrow(new org.springframework.security.access.AccessDeniedException("Unavailable"));mvc.perform(get(ownPath()+"/respond").with(user(client))).andExpect(status().isForbidden());mvc.perform(get(ownPath())).andExpect(status().is3xxRedirection());
    }
    @Test void sourceNoticeExportsKeepOwnerScopeAndPrivatePdfPrintHeaders()throws Exception{when(service.notice(client,id,true)).thenReturn("%PDF-notices".getBytes());for(var format:List.of("pdf","print"))mvc.perform(get(ownPath()+"/notice/"+format).with(user(client))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Content-Disposition",(format.equals("pdf")?"attachment":"inline")+"; filename=coverage-notices.pdf")).andExpect(content().contentType("application/pdf"));verify(service,times(2)).notice(client,id,true);}
    @Test void casePdfPrintRoutesRetainLanguageAndScopeAndRejectAnotherCycleBeforeRendering()throws Exception{
        reset(pdf);var staffDetail=new Detail(header,new Page<>(List.of(),0,false),new Page<>(List.of(),0,false),true,policy,data.notice(),day);var ownDetail=new Detail(header,staffDetail.events(),staffDetail.payments(),false,policy,data.notice(),day);
        when(service.document(staff,id,false)).thenReturn(staffDetail);when(service.document(client,id,true)).thenReturn(ownDetail);when(pdf.render(any(),any())).thenReturn("%PDF-case".getBytes());
        for(var locale:List.of(Locale.ENGLISH,Locale.of("sw")))for(var format:List.of("pdf","print"))for(var path:List.of(staffPath()+"/"+id,ownPath(),"/finance/groups/coverage/"+id)){
            boolean own=path.startsWith("/app/");mvc.perform(get(path+"/"+format).locale(locale).with(user(own?client:staff))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Content-Disposition",(format.equals("pdf")?"attachment":"inline")+"; filename=coverage-case.pdf")).andExpect(content().contentType("application/pdf"));verify(pdf,atLeastOnce()).render(own?ownDetail:staffDetail,locale);
        }
        clearInvocations(pdf);when(header.cycle()).thenReturn(UUID.randomUUID());mvc.perform(get(staffPath()+"/"+id+"/pdf").with(user(staff))).andExpect(status().isForbidden());verifyNoInteractions(pdf);
        when(service.document(client,id,true)).thenThrow(new org.springframework.security.access.AccessDeniedException("Unavailable"));mvc.perform(get(ownPath()+"/print").with(user(client))).andExpect(status().isForbidden());verifyNoInteractions(pdf);
    }
    @Test void oversizedCaseHistoryReturnsLocalizedRecoveryWithoutRendering()throws Exception{
        reset(pdf);when(service.document(staff,id,false)).thenThrow(new IllegalArgumentException("coverage.error.documentRange"));for(var locale:List.of(Locale.ENGLISH,Locale.of("sw")))mvc.perform(get(staffPath()+"/"+id+"/pdf").locale(locale).with(user(staff))).andExpect(status().isBadRequest()).andExpect(view().name("groups/error")).andExpect(model().attribute("groupError","coverage.error.documentRange")).andExpect(header().string("Cache-Control","no-store"));verifyNoInteractions(pdf);
    }
    @Test void staleReceiptRetainsVerificationAndRetryKeyWithoutPresentingTheSource()throws Exception{
        UUID key=UUID.randomUUID();when(service.link(eq(staff),eq(id),any())).thenThrow(new IllegalArgumentException("coverage.error.payment"));when(service.selectedPayment(staff,id,posting,null)).thenThrow(new IllegalArgumentException("coverage.error.payment"));
        var result=mvc.perform(post(staffPath()+"/"+id+"/link").with(user(staff)).with(csrf()).param("requestKey",key.toString()).param("postingId",posting.toString()).param("payerEvidence","Keep my checked payer evidence").param("payerVerified","true")).andExpect(status().isOk()).andExpect(view().name("groups/coverage-form")).andExpect(model().attribute("sourceUnavailable",true)).andExpect(model().attributeDoesNotExist("paymentSource")).andExpect(model().attributeHasErrors("coverageLinkForm")).andReturn();
        var form=(LinkForm)result.getModelAndView().getModel().get("coverageLinkForm");assertThat(form.getRequestKey()).isEqualTo(key);assertThat(form.getPayerEvidence()).isEqualTo("Keep my checked payer evidence");assertThat(form.isPayerVerified()).isTrue();
    }
    @Test void coverageOnlyClientClaimAllowsOnlyTheMemberSessionArea()throws Exception{var claims=EnumSet.of(UserClaim.GROUP_COVERAGE_OWN_VIEW);var only=new AppUserPrincipal(Member.builder().id(UUID.randomUUID()).saccoId("I1").stationId("B1").position(Position.MEMBER).memberAccount(true).status(MemberStatus.ACTIVE).build(),claims,false);assertThat(new com.sacco.mvp.service.AccessControlService().canAccessMemberArea(only)).isTrue();when(service.list(only,null,"newest",0,true)).thenReturn(new Page<>(List.of(),0,false));mvc.perform(get("/app/group-coverage").with(user(only))).andExpect(status().isOk()).andExpect(view().name("groups/coverage-register"));assertThat(new com.sacco.mvp.service.AccessControlService().canAccessMemberArea(staff)).isFalse();}
    @Test void allCoverageLabelsAndDynamicStatesExistInBothLanguages()throws Exception{for(var locale:List.of(Locale.ENGLISH,Locale.of("sw"))){var bundle=ResourceBundle.getBundle("messages",locale);for(var name:List.of("coverage-head.jspf","coverage-summary.jspf","coverage-register.jsp","coverage-picker.jsp","coverage-form.jsp","coverage-details.jsp")){var source=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/webapp/WEB-INF/jsp/groups",name));var matcher=java.util.regex.Pattern.compile("code=[\"']([^\"'$]+)[\"']").matcher(source);while(matcher.find())assertThat(bundle.containsKey(matcher.group(1))).as("%s %s",locale,matcher.group(1)).isTrue();}for(var key:List.of("CALLED","REQUESTED","ACKNOWLEDGED","PROMISED","DISPUTED","CANCELLED","CLOSED","UNAVAILABLE","RECEIVED","PART_RECEIVED","CURED_ELSEWHERE","EXPIRED"))assertThat(bundle.containsKey("coverage.state."+key)).isTrue();for(var key:List.of("RECIPROCAL","PERSONAL","JOINT","VOLUNTARY"))assertThat(bundle.containsKey("coverage.sourceKind."+key)).isTrue();}}
    @Configuration @EnableWebMvc static class Config {@Bean GroupCoverageService service(){return mock(GroupCoverageService.class);}@Bean GroupCoveragePdf pdf(){return mock(GroupCoveragePdf.class);}@Bean GroupCoverageDocumentController documents(GroupCoverageService s,GroupCoveragePdf p){return new GroupCoverageDocumentController(s,p);}@Bean GroupCoverageController controller(GroupCoverageService s){return new GroupCoverageController(s);}}
}
